    # Billing periods start on the first Tuesday of the month
    d = datetime.strptime(d_str, "%Y-%m-%d")
    starts = [
        datetime(2025, 3, 4),
        datetime(2025, 4, 1),
        datetime(2025, 5, 6),
        datetime(2025, 6, 3),
        datetime(2025, 7, 1)
    ]
    for i in range(len(starts) - 1):
        if starts[i] <= d < starts[i+1]:
            return i
    return -1

