import csv
import json
import math
from datetime import datetime, timedelta

def levenshtein(s1, s2):
    if len(s1) < len(s2): return levenshtein(s2, s1)
    if len(s2) == 0: return len(s1)
    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row
    return previous_row[-1]

def answer() -> dict[str, list[int]]:
    employees = {}
    with open("/app/dataset/employees.csv", "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            employees[row["PESEL"]] = float(row["hourly_rate"])

    valid_timesheets_raw = []
    min_date_str = "9999-99-99"
    with open("/app/dataset/timesheet.csv", "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            d_str = row["date"]
            try:
                datetime.strptime(d_str, "%Y-%m-%d")
            except ValueError:
                continue

            if d_str < min_date_str:
                min_date_str = d_str
            valid_timesheets_raw.append(row)

    min_date = datetime.strptime(min_date_str, "%Y-%m-%d")
    target_weekday = min_date.weekday()

    dedup = {}
    for row in valid_timesheets_raw:
        eid = row["employee_id"]
        if eid not in employees:
            eid = min(employees.keys(), key=lambda e: levenshtein(eid, e))

        d_str = row["date"]
        if (eid, d_str) not in dedup:
            dedup[(eid, d_str)] = row

    all_periods = set()
    employee_period_totals = {pesel: {} for pesel in employees}

    for (eid, d_str), row in dedup.items():
        d = datetime.strptime(d_str, "%Y-%m-%d")
        first_of_d_month = d.replace(day=1)
        offset = (target_weekday - first_of_d_month.weekday()) % 7
        start_of_d_month_period = first_of_d_month + timedelta(days=offset)

        if d < start_of_d_month_period:
            period_month = (d.month - 1) if d.month > 1 else 12
            period_year = d.year if d.month > 1 else d.year - 1
        else:
            period_month = d.month
            period_year = d.year

        period = (period_year, period_month)
        all_periods.add(period)

        rate = employees[eid]
        h = float(row["hours_worked"])
        b = float(row["bonus"])

        if period not in employee_period_totals[eid]:
            employee_period_totals[eid][period] = 0.0
        employee_period_totals[eid][period] += (h * rate + b)

    sorted_periods = sorted(list(all_periods))

    result = {}
    for pesel in employees:
        salaries = []
        for p in sorted_periods:
            val = employee_period_totals[pesel].get(p, 0.0)
            salaries.append(int(math.floor(val + 0.5)))
        result[pesel] = salaries

    return result

if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

